import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.BjY7aUvS.js";const b=JSON.parse('{"title":"食品标签 2027 新版 · 消费者问答精选","description":"GB 7718-2025 官方问答的消费者精选：保质期到期日、消费保存期、致敏物质怎么看、数字标签规则、豁免情形、进口食品日期。","frontmatter":{"title":"食品标签 2027 新版 · 消费者问答精选","issuer":"国家卫生健康委（标准问答）","source_tier":"一级来源","version":"GB 7718—2025","published":"2025-09","source_url":"https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml","status":"新版已发布（2027-03-16 实施）","tags":["国标","食品标签","消费者问答","行动清单"],"type":"国标科普","reviewed":false,"description":"GB 7718-2025 官方问答的消费者精选：保质期到期日、消费保存期、致敏物质怎么看、数字标签规则、豁免情形、进口食品日期。"},"headers":[],"relativePath":"standards/gb7718-qa-detail.md","filePath":"standards/gb7718-qa-detail.md"}'),s={name:"standards/gb7718-qa-detail.md"};function n(c,t,d,h,l,g){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="食品标签-2027-新版-·-消费者问答精选" tabindex="-1">食品标签 2027 新版 · 消费者问答精选 <a class="header-anchor" href="#食品标签-2027-新版-·-消费者问答精选" aria-label="Permalink to &quot;食品标签 2027 新版 · 消费者问答精选&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据国家卫健委官方问答整理，尚未逐条对照原文校验；校验通过前请以官方问答为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家卫健委官方问答</strong>（一级来源），逐条可点击溯源。本站不构成诊疗建议。</p></div><blockquote><p><strong>出处</strong>：<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">《食品安全国家标准 预包装食品标签通则》（GB 7718-2025）问答</a>。<strong>2027 年 3 月 16 日实施</strong>。配套阅读：<a href="/SageRelay/standards/gb7718-2025-preview.html">GB 7718 新旧对比</a>、<a href="/SageRelay/standards/gb7718-food-label.html">GB 7718 词条</a>。</p></blockquote><h2 id="消费者最常问的六件事" tabindex="-1">消费者最常问的六件事 <a class="header-anchor" href="#消费者最常问的六件事" aria-label="Permalink to &quot;消费者最常问的六件事&quot;">​</a></h2><h3 id="_1-保质期到底是什么" tabindex="-1">1. 保质期到底是什么？ <a class="header-anchor" href="#_1-保质期到底是什么" aria-label="Permalink to &quot;1. 保质期到底是什么？&quot;">​</a></h3><p>保质期 = 在标签标明的<strong>贮存条件下保持品质的期限</strong>，与《食品安全法》定义一致；<strong>超过保质期的食品不得用于生产和销售</strong>。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·保质期定义</a>）新版要求<strong>同时标示生产日期和保质期到期日</strong>两个日期——到期日从生产日当日或次日起算，不用自己再倒推。</p><h3 id="_2-长保质期食品也要印生产日期吗" tabindex="-1">2. 长保质期食品也要印生产日期吗？ <a class="header-anchor" href="#_2-长保质期食品也要印生产日期吗" aria-label="Permalink to &quot;2. 长保质期食品也要印生产日期吗？&quot;">​</a></h3><p><strong>保质期 6 个月及以上</strong>的食品，或包装最大表面面积 ≤20cm² 的小包装，标签可仅标示保质期和保质期到期日，<strong>生产日期改为自愿标示</strong>。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·日期标示</a>）</p><h3 id="_3-消费保存期-是什么-过了还能吃吗" tabindex="-1">3. &quot;消费保存期&quot;是什么？过了还能吃吗？ <a class="header-anchor" href="#_3-消费保存期-是什么-过了还能吃吗" aria-label="Permalink to &quot;3. &quot;消费保存期&quot;是什么？过了还能吃吗？&quot;">​</a></h3><p>新版鼓励企业自愿标示&quot;消费保存期&quot;作为<strong>最后食用日期参考</strong>（落实《反食品浪费法》），它<strong>不应短于保质期</strong>。但注意：<strong>超过保质期的食品仍不得用于生产和销售</strong>——消费保存期不改变保质期的法律要求。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·消费保存期</a>）</p><h3 id="_4-家里有过敏孩子-标签怎么看" tabindex="-1">4. 家里有过敏孩子，标签怎么看？ <a class="header-anchor" href="#_4-家里有过敏孩子-标签怎么看" aria-label="Permalink to &quot;4. 家里有过敏孩子，标签怎么看？&quot;">​</a></h3><p><strong>八大类致敏物质</strong>（含麸质谷物、甲壳纲如虾蟹、鱼、蛋、花生、大豆、乳、坚果）直接作为配料时，必须<strong>在配料表中加粗或下划线提示</strong>，或在配料表临近位置用&quot;致（过）敏物质提示&quot;等引导词；交叉污染鼓励标&quot;可能含有…&quot;预防性提示；芝麻、椰子等<strong>可自愿标示</strong>。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·致敏物质</a>）</p><h3 id="_5-扫码看的-数字标签-可信吗" tabindex="-1">5. 扫码看的&quot;数字标签&quot;可信吗？ <a class="header-anchor" href="#_5-扫码看的-数字标签-可信吗" aria-label="Permalink to &quot;5. 扫码看的&quot;数字标签&quot;可信吗？&quot;">​</a></h3><p>新版鼓励数字标签：内容必须符合强制标示规定、与注册备案信息一致（保健食品等）、<strong>不得有弹窗飘窗等干扰元素</strong>、修改须记录并可追溯。生产企业对展示内容真实性负责——遇到扫码全是广告弹窗的，不符合新规。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·数字标签</a>）</p><h3 id="_6-进口食品没有生产日期怎么办" tabindex="-1">6. 进口食品没有生产日期怎么办？ <a class="header-anchor" href="#_6-进口食品没有生产日期怎么办" aria-label="Permalink to &quot;6. 进口食品没有生产日期怎么办？&quot;">​</a></h3><p>原标签仅有&quot;保质期/最佳食用日期&quot;的进口食品，进口商应据此<strong>推算并以加贴、补印等方式标示生产日期</strong>。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·进口食品</a>）</p><h2 id="附录-·-豁免与特例" tabindex="-1">附录 · 豁免与特例 <a class="header-anchor" href="#附录-·-豁免与特例" aria-label="Permalink to &quot;附录 · 豁免与特例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情形</th><th>规则</th><th>出处</th></tr></thead><tbody><tr><td>葡萄酒及酒精度 ≥10% 的酒类</td><td>标示批号的前提下可免标生产日期、保质期与到期日（批号不得加贴补印修改）</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·豁免</a></td></tr><tr><td>普洱茶、黑茶等</td><td>适宜贮存下可长期保存的，到期日可标&quot;长期保存&quot;</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·普洱茶</a></td></tr><tr><td>&quot;固体食糖&quot;豁免</td><td>指白砂糖、绵白糖、红糖、冰糖等，<strong>不包括糖果</strong></td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·豁免</a></td></tr><tr><td>包装 ≤20cm²</td><td>可免除部分标示内容</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">问答·豁免</a></td></tr></tbody></table><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>版本</td><td>GB 7718—2025（2027-03-16 实施）</td></tr><tr><td>归口</td><td>国家卫生健康委（食品安全国家标准）</td></tr><tr><td>出处</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/bc824a504ec34c27883da73f14c20d44.shtml" target="_blank" rel="noreferrer">官方问答页</a> · <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=7718" target="_blank" rel="noreferrer">标准查询（全文公开系统）</a></td></tr></tbody></table>',21)])])}const p=a(s,[["render",n]]);export{b as __pageData,p as default};
